// Authored example: apply number formats to cells and read the formatted text after a save and reload.
use aspose_cells_foss_rust::Workbook;
use std::error::Error;

fn main() -> Result<(), Box<dyn Error>> {
    let mut workbook = Workbook::new();
    {
        let mut worksheets = workbook.get_worksheets_mut();
        let sheet = worksheets.get(0)?;
        let mut cells = sheet.get_cells_mut();
        let mut price = cells.get("A1")?;
        price.put_value_decimal(1234.5)?;
        price.apply_number_format("#,##0.00")?;
        let mut rate = cells.get("B1")?;
        rate.put_value_decimal(0.256)?;
        rate.apply_number_format("0.0%")?;
    }

    // Save to a temporary file, reload it, then delete the file again.
    let path = std::env::temp_dir().join("authored_number_format_example.xlsx");
    workbook.save(&path)?;
    let loaded = Workbook::load_xlsx(&path)?;
    std::fs::remove_file(&path)?;

    let sheet = loaded.worksheet("Sheet1")?;
    let cells = sheet.get_cells();
    let price = cells.get("A1")?;
    let rate = cells.get("B1")?;
    println!("price: {} -> {}", price.raw_string_value(), price.formatted_string_value());
    println!("rate: {} -> {}", rate.raw_string_value(), rate.formatted_string_value());

    assert_eq!(price.double_value(), Some(1234.5));
    assert_eq!(price.formatted_string_value(), "1,234.50");
    assert_eq!(rate.formatted_string_value(), "25.6%");
    Ok(())
}
