// Authored example: add a second worksheet, fill it with data and read a cell back after reloading the workbook.
use aspose_cells_foss_rust::Workbook;
use std::error::Error;

fn main() -> Result<(), Box<dyn Error>> {
    let mut workbook = Workbook::new();
    workbook.add_worksheet("Totals")?;
    {
        let mut worksheets = workbook.get_worksheets_mut();
        let sheet = worksheets.get_by_name("Totals")?;
        let mut cells = sheet.get_cells_mut();
        cells.get("A1")?.put_value_string("Quarter")?;
        cells.get("B1")?.put_value_string("Revenue")?;
        cells.get("A2")?.put_value_string("Q1")?;
        cells.get("B2")?.put_value_i32(1500)?;
    }

    let bytes = workbook.save_xlsx_to_bytes()?;
    let loaded = Workbook::load_xlsx_from_bytes(&bytes)?;

    let worksheets = loaded.get_worksheets();
    println!("worksheets: {}", worksheets.count());

    let totals = loaded.worksheet("Totals")?;
    let cells = totals.get_cells();
    println!("{} = {}", cells.get("B1")?.display_string_value(), cells.get("B2")?.display_string_value());

    assert_eq!(worksheets.count(), 2);
    assert_eq!(totals.get_name(), "Totals");
    assert_eq!(cells.get("B2")?.int_value(), Some(1500));
    Ok(())
}
